/**
 * This event is generated by nsMsgStatusFeedback when it gets an
 * OnStateChange event for STATE_STOP.  This is the same event that
 * generates the "msgLoaded" property flag change event.  This best
 * corresponds to the end of the streaming process.
 *
 * @param {nsIURI} url
 */
async onEndMsgDownload(url) {
  const browser = getMessagePaneBrowser();
  // Everything here is about the message which just loaded. The message pane
  // can navigate away before or while we do it, and once it has, there's
  // nothing left to do.
  const isStillDisplayed = () => url.equals(browser.currentURI);
  if (!isStillDisplayed()) {
    return;
  }
